CREATE TABLE public.team_join_requests(team_id uuid NOT NULL REFERENCES public.teams(id) ON DELETE CASCADE,user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','declined','removed')),requested_at timestamptz NOT NULL DEFAULT now(),decided_at timestamptz,decided_by uuid,invite_id uuid REFERENCES public.team_invites(id),PRIMARY KEY(team_id,user_id));
GRANT SELECT ON public.team_join_requests TO authenticated; GRANT ALL ON public.team_join_requests TO service_role;
ALTER TABLE public.team_join_requests ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Requester or sole owner reads request" ON public.team_join_requests FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.team_channel_owner(team_id));
CREATE FUNCTION public.request_team_membership(_team uuid,_invite uuid DEFAULT NULL) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r team_join_requests; BEGIN
IF auth.uid() IS NULL THEN RAISE EXCEPTION 'auth_required'; END IF;
IF NOT EXISTS(SELECT 1 FROM profiles WHERE id=auth.uid() AND adult_confirmed_at IS NOT NULL) THEN RAISE EXCEPTION 'adult_required'; END IF;
IF EXISTS(SELECT 1 FROM user_suspensions WHERE user_id=auth.uid()) OR EXISTS(SELECT 1 FROM team_suspensions WHERE team_id=_team) OR EXISTS(SELECT 1 FROM community_suspensions WHERE team_id=_team AND user_id=auth.uid() AND revoked_at IS NULL) THEN RAISE EXCEPTION 'forbidden'; END IF;
IF public.team_channel_access(_team) THEN RETURN 'approved'; END IF;
IF EXISTS(SELECT 1 FROM team_members WHERE team_id=_team AND user_id=auth.uid()) THEN RAISE EXCEPTION 'forbidden'; END IF;
INSERT INTO team_join_requests(team_id,user_id,invite_id) VALUES(_team,auth.uid(),_invite) ON CONFLICT(team_id,user_id) DO NOTHING;
SELECT * INTO r FROM team_join_requests WHERE team_id=_team AND user_id=auth.uid();
IF r.status='pending' THEN PERFORM public.notify_users(ARRAY[(SELECT owner_id FROM teams WHERE id=_team)],'announcement',CASE WHEN (SELECT language FROM profiles WHERE id=(SELECT owner_id FROM teams WHERE id=_team))='es' THEN 'Solicitud para unirse al equipo' ELSE 'Team join request' END,(SELECT coalesce(full_name,'') FROM profiles WHERE id=auth.uid()),'/team?team='||_team||'&panel=members','team-request:'||_team||':'||auth.uid()); END IF;
RETURN r.status; END $$;
CREATE OR REPLACE FUNCTION public.join_team_by_code(_code text,_role text DEFAULT 'member',_by uuid DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE t uuid; BEGIN SELECT id INTO t FROM teams WHERE join_code=upper(trim(_code)); IF t IS NULL THEN RAISE EXCEPTION 'invalid_code'; END IF; PERFORM public.request_team_membership(t); RETURN t; END $$;
CREATE OR REPLACE FUNCTION public.accept_team_invite(_token text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE i team_invites; e text; s text; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'auth_required'; END IF; SELECT * INTO i FROM team_invites WHERE token=upper(trim(_token)) FOR UPDATE; IF i.id IS NULL THEN RAISE EXCEPTION 'invalid_invite'; END IF;
IF EXISTS(SELECT 1 FROM team_join_requests WHERE team_id=i.team_id AND user_id=auth.uid() AND invite_id=i.id) THEN RETURN jsonb_build_object('team_id',i.team_id,'status',(SELECT status FROM team_join_requests WHERE team_id=i.team_id AND user_id=auth.uid())); END IF;
IF i.revoked_at IS NOT NULL THEN RAISE EXCEPTION 'invite_revoked'; END IF; IF i.expires_at<=now() THEN RAISE EXCEPTION 'invite_expired'; END IF; IF i.accepted_at IS NOT NULL AND i.accepted_by IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION 'invite_used'; END IF; SELECT email INTO e FROM auth.users WHERE id=auth.uid(); IF lower(e) IS DISTINCT FROM lower(i.email) THEN RAISE EXCEPTION 'email_mismatch'; END IF;
s:=public.request_team_membership(i.team_id,i.id); UPDATE team_invites SET accepted_at=now(),accepted_by=auth.uid() WHERE id=i.id; RETURN jsonb_build_object('team_id',i.team_id,'status',s); END $$;
CREATE FUNCTION public.decide_team_request(_team uuid,_user uuid,_decision text) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r team_join_requests; BEGIN IF NOT public.team_channel_owner(_team) THEN RAISE EXCEPTION 'forbidden'; END IF; IF _decision NOT IN ('approved','declined','removed') OR _user=(SELECT owner_id FROM teams WHERE id=_team) THEN RAISE EXCEPTION 'invalid_decision'; END IF;
PERFORM 1 FROM teams WHERE id=_team FOR UPDATE;
IF _decision='removed' THEN INSERT INTO team_join_requests(team_id,user_id,status) VALUES(_team,_user,'approved') ON CONFLICT DO NOTHING; END IF;
SELECT * INTO r FROM team_join_requests WHERE team_id=_team AND user_id=_user FOR UPDATE; IF r.team_id IS NULL THEN RAISE EXCEPTION 'not_found'; END IF; IF r.status=_decision THEN RETURN r.status; END IF; IF _decision IN ('approved','declined') AND r.status<>'pending' THEN RAISE EXCEPTION 'invalid_state'; END IF;
IF _decision='approved' THEN IF EXISTS(SELECT 1 FROM user_suspensions WHERE user_id=_user) OR EXISTS(SELECT 1 FROM community_suspensions WHERE team_id=_team AND user_id=_user AND revoked_at IS NULL) THEN RAISE EXCEPTION 'forbidden'; END IF; INSERT INTO team_members(team_id,user_id,role,workspace_role) VALUES(_team,_user,'member','member') ON CONFLICT DO NOTHING;
ELSE DELETE FROM team_members WHERE team_id=_team AND user_id=_user; END IF;
UPDATE team_join_requests SET status=_decision,decided_at=now(),decided_by=auth.uid() WHERE team_id=_team AND user_id=_user;
PERFORM public.team_log(_team,'membership.'||_decision,_user,'{}');
PERFORM public.notify_users(ARRAY[_user],'announcement',CASE WHEN (SELECT language FROM profiles WHERE id=_user)='es' THEN 'Estado del equipo actualizado' ELSE 'Team status updated' END,(SELECT name FROM teams WHERE id=_team),CASE WHEN _decision='approved' THEN '/team?team='||_team ELSE '/me?panel=teams' END,'team-decision:'||_team||':'||_user||':'||_decision);
RETURN _decision; END $$;
CREATE OR REPLACE FUNCTION public.remove_member(_team uuid,_user uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM public.decide_team_request(_team,_user,'removed'); END $$;
CREATE FUNCTION public.my_team_states() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce(jsonb_agg(jsonb_build_object('team_id',t.id,'name',t.name,'slug',t.slug,'owner',t.owner_id=auth.uid(),'role',CASE WHEN t.owner_id=auth.uid() THEN 'leader' ELSE coalesce(m.role,'member') END,'status',CASE WHEN m.suspended_at IS NOT NULL THEN 'suspended' WHEN public.team_channel_access(t.id) THEN 'approved' ELSE coalesce(r.status,'unavailable') END,'access',public.team_channel_access(t.id),'requested_at',r.requested_at,'joined_at',m.joined_at) ORDER BY t.name),'[]') FROM teams t LEFT JOIN team_members m ON m.team_id=t.id AND m.user_id=auth.uid() LEFT JOIN team_join_requests r ON r.team_id=t.id AND r.user_id=auth.uid() WHERE auth.uid() IS NOT NULL AND (t.owner_id=auth.uid() OR m.user_id IS NOT NULL OR r.user_id IS NOT NULL) $$;
CREATE FUNCTION public.team_member_management(_team uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.team_channel_owner(_team) THEN RAISE EXCEPTION 'forbidden'; END IF; RETURN jsonb_build_object('members',(SELECT coalesce(jsonb_agg(jsonb_build_object('user_id',m.user_id,'name',p.full_name,'slug',CASE WHEN p.host_public THEN p.slug END,'role',CASE WHEN m.user_id=t.owner_id THEN 'leader' ELSE m.role END,'status',CASE WHEN m.suspended_at IS NOT NULL THEN 'suspended' ELSE 'approved' END,'joined_at',m.joined_at,'requested_at',r.requested_at) ORDER BY m.joined_at),'[]') FROM team_members m JOIN profiles p ON p.id=m.user_id JOIN teams t ON t.id=m.team_id LEFT JOIN team_join_requests r ON r.team_id=m.team_id AND r.user_id=m.user_id WHERE m.team_id=_team),'requests',(SELECT coalesce(jsonb_agg(jsonb_build_object('user_id',r.user_id,'name',p.full_name,'slug',CASE WHEN p.host_public THEN p.slug END,'role','member','status',r.status,'requested_at',r.requested_at,'decided_at',r.decided_at) ORDER BY r.requested_at),'[]') FROM team_join_requests r JOIN profiles p ON p.id=r.user_id WHERE r.team_id=_team AND r.status<>'approved')); END $$;
CREATE POLICY "Sole owner roster, self membership only" ON public.team_members AS RESTRICTIVE FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.team_channel_owner(team_id));
CREATE POLICY "Sole owner member insert" ON public.team_members AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK(public.team_channel_owner(team_id));
CREATE POLICY "Sole owner member update" ON public.team_members AS RESTRICTIVE FOR UPDATE TO authenticated USING(public.team_channel_owner(team_id)) WITH CHECK(public.team_channel_owner(team_id));
CREATE POLICY "Sole owner removal or leave" ON public.team_members AS RESTRICTIVE FOR DELETE TO authenticated USING(public.team_channel_owner(team_id) OR user_id=auth.uid());
CREATE FUNCTION public.record_membership_removal() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF EXISTS(SELECT 1 FROM teams WHERE id=OLD.team_id) AND EXISTS(SELECT 1 FROM profiles WHERE id=OLD.user_id) THEN INSERT INTO team_join_requests(team_id,user_id,status,decided_at,decided_by) VALUES(OLD.team_id,OLD.user_id,'removed',now(),auth.uid()) ON CONFLICT(team_id,user_id) DO UPDATE SET status='removed',decided_at=now(),decided_by=auth.uid(); END IF; RETURN OLD; END $$;
CREATE TRIGGER team_members_removal_state AFTER DELETE ON public.team_members FOR EACH ROW EXECUTE FUNCTION public.record_membership_removal();
REVOKE ALL ON FUNCTION public.request_team_membership(uuid,uuid),public.my_team_states(),public.team_member_management(uuid),public.decide_team_request(uuid,uuid,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.request_team_membership(uuid,uuid),public.my_team_states(),public.team_member_management(uuid),public.decide_team_request(uuid,uuid,text) TO authenticated;
ALTER PUBLICATION supabase_realtime ADD TABLE public.team_join_requests;